export const RAV_ASSISTANT_PRODUCT_EXAMPLES = Object.freeze(Object.fromEntries(
  RAV_ASSISTANT_PRODUCT_KNOWLEDGE.map(item => [item.id, item.examples])
));

function topic(id, pattern, examples, answers, shortAnswers=null) {
  const sourceIds = ['rr-current-product', 'rr-user-spec'];
  if (!validateRavAssistantSourceIds(sourceIds)) throw new Error('Unknown public product source');
  return Object.freeze({ id, pattern, evidenceClass:'ravradar-product',
    sourceIds:Object.freeze(sourceIds), examples:Object.freeze(examples),
    answers:Object.freeze(Object.fromEntries(['da','de','en'].map((locale,index)=>[locale,answers[index]]))),
    ...(shortAnswers ? { shortAnswers:Object.freeze(Object.fromEntries(['da','de','en'].map((locale,index)=>[locale,shortAnswers[index]]))) } : {}) });
}

function completeHelpRequests(questions) {
  // Complete, authored help questions only. Never drop a person's name,
  // status request, credentials, date or other unsupported qualification.
  const requests=questions.map(question=>question
    .replace(/[.!?\s]+$/u,'').split(/\s+/u)
    // German uppercase turns ß into SS. Preserve complete question anchoring
    // while admitting this spelling; never strip unsupported qualifications.
    .map(word=>word.replace(/[.*+?^${}()|[\]\\]/gu,'\\$&')
      .replace(/ß/gu,'(?:ß|ss)')).join(String.raw`\s+`));
  return '^(?:'+requests.join('|')+')[.!?\\s]*$';
}

function helpAliases(pattern, variants) {
  // Keep the existing topic/answer rather than counting new phrasings as
  // new knowledge. Aliases add only complete, authored questions.
  return new RegExp('(?:'+pattern.source+')|(?:'+completeHelpRequests(variants)+')',pattern.flags);
}

function productHelp(id, examples, answers, variants=[]) {
  return topic(id,new RegExp(completeHelpRequests([...examples,...variants]),'iu'),examples,answers);
}
